    private static void draw(int[][] grid, List<int[]> path) {
        StringBuilder grid_pattern = new StringBuilder();
        for (int i = -1; i < grid.length + 1; i++) {
            for (int j = -1; j < grid[0].length + 1; j++) {
                if (i < 0 || j < 0 || i == grid.length || j == grid[0].length) {
                    grid_pattern.append("██");
                } else {
                    if (path != null && contains(i, j, path)) {
                        grid_pattern.append("\033[0;31m██\33[0m");
                    } else if (grid[i][j] == 1)
                        grid_pattern.append("  ");
                    else
                        grid_pattern.append("██");
                }
            }
            grid_pattern.append("\n");
        }
        System.out.println(grid_pattern);
    }

    private static boolean contains(int i, int j, List<int[]> path) {
        for (int[] point : path) {
            if (point[0] == i && point[1] == j) {
                return true;
            }
        }
        return false;
    }

    public static int[][] generate_grid(int row, int col) {
        int[][] grid = new int[row][col];
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                var r = (int) ((Math.random() * (i + j))) % (3);
                grid[i][j] = r != 0 ? 1 : 0;
            }
        }
        return grid;
    }
